// Isolation test (OS-12) — construct DrawContextLog with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21, MF-22.)
import { describe, expect, it } from "vitest";
import { height, noSubject, type RecordHeight } from "../src/kernel/index.js";
import { DeclarationLedger, type Unit } from "../src/catalog/index.js";
import { DrawContextLog, type DeclarationReader } from "../src/facts/index.js";
import { inMemoryRecord, type TestRecord } from "./catalog/in-memory-record.js";

const u = "u1" as Unit;
const features = { colour: "red" };
const nothingDeclared: DeclarationReader = { declarationAt: () => noSubject() };

/** A record holding a declaration for `u`, and the reader that answers it. */
function declared(): { record: TestRecord; declarations: DeclarationReader; at: RecordHeight } {
  const record = inMemoryRecord();
  const declarations = new DeclarationLedger({ record, levels: ["easy"] });
  declarations.declare(u, "easy", "HUMAN");
  return { record, declarations, at: record.noise() };
}

describe("DrawContextLog in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new DrawContextLog({ declarations: nothingDeclared } as never)).toThrow();
    expect(() => new DrawContextLog({ record: inMemoryRecord() } as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new DrawContextLog({ record: {} as never, declarations: nothingDeclared })).toThrow();
    expect(() => new DrawContextLog({ record: inMemoryRecord(), declarations: {} as never })).toThrow();
  });

  it("recordDraw answers differently when declarations differs", () => {
    const { record, declarations, at } = declared();
    const a = new DrawContextLog({ record, declarations }).recordDraw(u, features, at, "c", at, "ENGINE");
    const b = new DrawContextLog({ record, declarations: nothingDeclared }).recordDraw(u, features, at, "c", at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("recordDraw answers differently when record differs", () => {
    const one = declared();
    const two = declared();
    two.record.noise();
    const a = new DrawContextLog(one).recordDraw(u, features, one.at, "c", one.at, "ENGINE");
    const b = new DrawContextLog(two).recordDraw(u, features, one.at, "c", one.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("label answers differently when record differs", () => {
    const one = declared();
    const two = declared();
    const k = new DrawContextLog(one).recordDraw(u, features, one.at, "c", one.at, "ENGINE");
    if (!("payload" in k)) throw new Error("setup: the draw was refused");
    two.record.noise();
    two.record.noise();
    const a = new DrawContextLog(one).label(k, "DRAW", "HUMAN");
    const b = new DrawContextLog(two).label(k, "DRAW", "HUMAN");
    expect(a).not.toEqual(b);
  });

  it("drawsAsOf answers differently when record differs", () => {
    const one = declared();
    const two = declared();
    const log = new DrawContextLog(one);
    const k = log.recordDraw(u, features, one.at, "c", one.at, "ENGINE");
    if (!("payload" in k)) throw new Error("setup: the draw was refused");
    const a = log.drawsAsOf(u, k.at);
    const b = new DrawContextLog(two).drawsAsOf(u, k.at);
    expect(a).not.toEqual(b);
  });

  it("resolutionAt answers differently when record differs", () => {
    const one = declared();
    const log = new DrawContextLog(one);
    const k = log.recordDraw(u, features, one.at, "c", one.at, "ENGINE");
    if (!("payload" in k)) throw new Error("setup: the draw was refused");
    const labelled = log.label(k, "REVISION", "HUMAN");
    const a = log.resolutionAt(k, labelled.at);
    const b = new DrawContextLog(declared()).resolutionAt(k, height(Number(labelled.at)));
    expect(a).not.toEqual(b);
  });
});
